    'card.toan.title':          { vi: 'Toán Lớp 1',                         en: 'Grade 1 Math',                         ja: '小1さんすう',                       zh: '一年级数学',                    ar: 'رياضيات أول ابتدائي' },
    'card.toan.desc':           { vi: '5 trò trong 1: cộng trừ đến 20, so sánh > < = với cái cân, xem giờ, hình khối & quy luật, đi chợ trả tiền.', en: '5 games in 1: add & subtract to 20, compare with a balance scale, tell time, shapes & patterns, go shopping.', ja: '5つの遊び：20までのたし算ひき算、てんびんで比べる、時計、形と規則、お買い物。', zh: '五合一：20以内加减、天平比大小、认时钟、图形与规律、购物付钱。', ar: 'خمس ألعاب: جمع وطرح حتى 20، مقارنة بالميزان، قراءة الساعة، أشكال وأنماط، تسوّق.' },
    'toan.title':               { vi: '➕ Toán Lớp 1',                      en: '➕ Grade 1 Math',                      ja: '➕ さんすう',                       zh: '➕ 数学',                        ar: '➕ رياضيات' },
    'toan.help.add':            { vi: 'Điền hoặc chọn đáp án đúng cho phép tính cộng trừ hiện trên màn hình.', en: 'Fill in or choose the correct answer for the addition/subtraction problem shown.', ja: 'がめんのたしざん・ひきざんのこたえをえらぶかにゅうりょくしよう。', zh: '填写或选择屏幕上加减法题目的正确答案。', ar: 'املأ أو اختر الإجابة الصحيحة لمسألة الجمع أو الطرح المعروضة.' },
    'toan.help.compare':        { vi: 'Chạm vào dấu lớn hơn, bé hơn hoặc bằng cho phù hợp giữa 2 bên.', en: 'Tap the greater-than, less-than or equal sign that fits between the two sides.', ja: 'りょうがわにあうように、だいなり・しょうなり・イコールのきごうをタップしよう。', zh: '点击大于、小于或等于符号，使其适合两边的数量关系。', ar: 'انقر إشارة أكبر من أو أصغر من أو يساوي المناسبة بين الطرفين.' },
    'toan.help.clock':          { vi: 'Nhìn đồng hồ rồi chọn đúng giờ, hoặc xoay kim đồng hồ cho đúng giờ được yêu cầu.', en: 'Look at the clock and choose the right time, or turn the clock hands to the requested time.', ja: 'とけいをみてただしいじかんをえらぶか、とけいのはりをうごかしてあわせよう。', zh: '看时钟选择正确的时间，或转动时针分针调到要求的时间。', ar: 'انظر إلى الساعة واختر الوقت الصحيح، أو أدر عقارب الساعة إلى الوقت المطلوب.' },
    'toan.help.shape':          { vi: 'Chọn hình khối giống mẫu, hoặc tìm hình tiếp theo đúng quy luật.', en: 'Choose the shape that matches the sample, or find the next shape in the pattern.', ja: 'おてほんとおなじかたちをえらぶか、つぎにくるかたちをみつけよう。', zh: '选择与样本相同的形状，或找出规律中的下一个图形。', ar: 'اختر الشكل المطابق للنموذج، أو أوجد الشكل التالي في النمط.' },
    'toan.help.shop':           { vi: 'Chạm vào các tờ tiền để trả đúng số tiền cần mua hàng.', en: 'Tap the bills to pay the exact amount needed for the items.', ja: 'おかねをタップして、しなもののきんがくどおりにしはらおう。', zh: '点击钞票支付购买商品所需的准确金额。', ar: 'انقر الأوراق النقدية لدفع المبلغ المطلوب بالضبط للسلع.' },
    'toan.tab.add':             { vi: 'Cộng trừ',                           en: 'Add & subtract',                       ja: 'たしひき',                          zh: '加减',                          ar: 'جمع وطرح' },
