    'daovang.shop.go':          { vi: 'ĐI MUA ĐỒ ▶',                        en: 'GO SHOPPING ▶',                        ja: 'おかいもの ▶',                      zh: '去购物 ▶',                      ar: 'اذهب للتسوق ▶' },
