    'card.dientu.title':        { vi: 'Điện Tử Xưa',                        en: 'Retro Arcade',                         ja: 'レトロゲーム機',                    zh: '怀旧电玩',                      ar: 'ألعاب قديمة' },
    'card.dientu.desc':         { vi: '3 game máy điện tử ngày bé: bắn vịt trời (chế độ học số chẵn), đập gạch nhặt chữ cái, đua xe lao vào cổng đáp án toán.', en: '3 retro arcade games: duck hunt (even-number mode), brick breaker with falling letters, lane racer with math answer gates.', ja: 'ダックハント、ブロック崩し、レーンレーサーの3本。学習モード付き。', zh: '打鸭子（偶数模式）、打砖块捡字母、赛车冲对答案门。', ar: 'صيد البط، كسر الطوب، سباق مع بوابات الإجابات.' },
    'dientu.title':             { vi: '🕹️ Điện Tử Xưa',                    en: '🕹️ Retro Arcade',                     ja: '🕹️ レトロゲーム',                  zh: '🕹️ 怀旧电玩',                  ar: '🕹️ ألعاب قديمة' },
    'dientu.help.ducks':        { vi: 'Chạm vào con vịt bay qua màn hình để bắn hạ! Chọn chế độ "Chỉ số chẵn" nếu muốn chỉ bắn vịt mang số chẵn thôi.', en: 'Tap the ducks flying across the screen to shoot them down! Choose "Even numbers only" to only shoot ducks carrying even numbers.', ja: 'がめんをとぶあひるをタップしてうちおとそう！「ぐうすうだけ」モードでは、ぐうすうのあひるだけうとう。', zh: '点击飞过屏幕的鸭子把它打下来！选择"仅偶数"模式只打带偶数的鸭子。', ar: 'انقر البط الطائر عبر الشاشة لإسقاطه! اختر "الأرقام الزوجية فقط" لضرب البط ذي الأرقام الزوجية فقط.' },
    'dientu.help.bricks':       { vi: 'Kéo thanh trượt để đỡ quả bóng nảy lên, phá hết các viên gạch phía trên nhé! Đừng để bóng rơi xuống dưới.', en: 'Drag the paddle to bounce the ball up and break all the bricks above! Don\'t let the ball fall to the bottom.', ja: 'バーをうごかしてボールをはねかえし、うえのブロックをぜんぶこわそう！ボールをおとさないでね。', zh: '拖动挡板把球弹起来，打碎上面所有的砖块！别让球掉到下面去。', ar: 'اسحب المضرب لارتداد الكرة وتكسير كل الطوب أعلاه! لا تدع الكرة تسقط إلى الأسفل.' },
    'dientu.help.racer':        { vi: 'Vuốt trái phải hoặc chạm vào làn đường để né các xe khác, đi được càng xa càng nhiều điểm!', en: 'Swipe left/right or tap a lane to dodge other cars — the farther you go, the more points you get!', ja: 'ひだりみぎにスワイプするか、レーンをタップしてほかのくるまをよけよう。とおくまでいくほどとくてん！', zh: '左右滑动或点击车道躲避其他车辆，走得越远分数越高！', ar: 'اسحب يسارًا/يمينًا أو انقر مسارًا لتفادي السيارات الأخرى — كلما ذهبت أبعد سجلت نقاطًا أكثر!' },
    'dientu.ducks':             { vi: 'Bắn vịt trời',                       en: 'Duck hunt',                            ja: 'ダックハント',                      zh: '打鸭子',                        ar: 'صيد البط' },
    'dientu.bricks':            { vi: 'Đập gạch bóng nảy',                  en: 'Brick breaker',                        ja: 'ブロック崩し',                      zh: '打砖块',                        ar: 'كسر الطوب' },
    'dientu.racer':             { vi: 'Đua xe né chướng ngại',              en: 'Lane racer',                           ja: 'レーンレーサー',                    zh: '赛车避障',                      ar: 'سباق المسارات' },
    'dientu.ducks.all':         { vi: '🦆 Bắn hết',                         en: '🦆 Shoot all',                         ja: '🦆 ぜんぶ撃つ',                     zh: '🦆 全都打',                     ar: '🦆 اضرب الكل' },
    'dientu.ducks.even':        { vi: '🔢 Chỉ số CHẴN',                     en: '🔢 EVEN numbers only',                 ja: '🔢 偶数だけ',                       zh: '🔢 只打偶数',                   ar: '🔢 الأرقام الزوجية فقط' },
    'dientu.ducks.hit':         { vi: 'Bắn trúng',                          en: 'Hit',                                  ja: '命中',                              zh: '击中',                          ar: 'أصبت' },
