    'dientu.bricks.win':        { vi: 'Phá hết gạch!',                      en: 'All bricks cleared!',                  ja: '全ブロック破壊！',                  zh: '砖块全清！',                    ar: 'كسرت كل الطوب!' },
    'dientu.racer.classic':     { vi: '🚕 Né chướng ngại',                  en: '🚕 Dodge obstacles',                   ja: '🚕 障害物よけ',                     zh: '🚕 避开障碍',                   ar: '🚕 تفادى العوائق' },
