    'examprep.movers.desc':     { vi: 'Nền tảng ngữ pháp: hiện tại đơn/tiếp diễn, quá khứ đơn, can, so sánh hơn', en: 'Grammar foundation: present simple/continuous, past simple, can, comparatives', ja: 'きそぶんぽう：げんざいけい・げんざいしんこうけい・かこけい・can・ひかくきゅう', zh: '语法基础：现在时/进行时、过去时、can、比较级', ar: 'أساسيات القواعد: المضارع البسيط/المستمر، الماضي البسيط، can، المقارنة' },
    'examprep.flyers':          { vi: 'Flyers (A2)',                        en: 'Flyers (A2)',                          ja: 'Flyers (A2)',                      zh: 'Flyers (A2)',                  ar: 'Flyers (A2)' },
