    'examprep.ket':             { vi: 'KET (A2 Key)',                        en: 'KET (A2 Key)',                          ja: 'KET (A2 Key)',                      zh: 'KET (A2 Key)',                  ar: 'KET (A2 Key)' },
    'examprep.ket.desc':        { vi: 'Chứng chỉ đầu tiên có điểm: câu điều kiện loại 0/1, động từ + V-ing, đại từ phản thân, cụm động từ cơ bản', en: 'The first scored certificate: 0/1 conditionals, verb + V-ing, reflexive pronouns, basic phrasal verbs', ja: 'はじめてとくてんがつくしけん：じょうけんぶん0/1、どうし+V-ing、さいきだいめいし、くじゅつどうし', zh: '第一个有分数的证书：0/1条件句、动词+V-ing、反身代词、基础短语动词', ar: 'أول شهادة بدرجات: الجمل الشرطية 0/1، فعل + V-ing، الضمائر الانعكاسية، الأفعال العبارية الأساسية' },
    'examprep.pet':             { vi: 'PET (B1 Preliminary)',                en: 'PET (B1 Preliminary)',                  ja: 'PET (B1 Preliminary)',              zh: 'PET (B1 Preliminary)',          ar: 'PET (B1 Preliminary)' },
